pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: from address, value v, and index count for tos array length
    function testFuzz_property(address from, uint256 v, uint8 tosCount) public {
        // keep tosCount in a reasonable range but wide enough
        uint8 n = bound(tosCount, 1, 8);

        // deploy an adversarial callee that, when called via transferFrom selector,
        // will modify storage in the callee contract. This demonstrates that
        // using delegatecall would instead modify C's storage (bug), while call
        // would modify only the callee.
        Adversary adv = new Adversary();

        // build tos array of the adversary address repeated n times
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) tos[i] = address(adv);

        // Record a public observable of c before the call: its contract balance
        // (must be observable via address(c).balance). Ensure nonzero to avoid irrelevant zero-case.
        vm.deal(address(this), 1 ether);
        // send some ether to c so balance is nonzero and can be observed
        payable(address(c)).transfer(1 wei);
        uint256 beforeBal = address(c).balance;

        // Also observe a getter-like behaviour: try/catch the call to see it returns/doesn't revert
        bool ok;
        try c.transfer(from, address(adv), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the correct implementation (using call) does NOT let the callee
        // mutate c's storage. Therefore, c's balance (an observable property) remains unchanged.
        // The mutant using delegatecall can cause the callee code to alter c's storage, and
        // may affect observable state (here we check balance as a stable observable provided by C).
        uint256 afterBal = address(c).balance;

        // The universal property asserted: for all admissible inputs, the reference preserves its own balance
        // across transfer invocation (i.e., beforeBal == afterBal). The buggy mutant using delegatecall can
        // break this for some inputs (the fuzzer can find such cases).
        assertTrue(beforeBal == afterBal);
    }
}

// Adversarial helper: exposes a function matching transferFrom selector and modifies its own storage.
// When called with call, it changes its own storage only; when invoked via delegatecall (mutant), it would
// modify the storage of the caller (C), thus making the difference observable.
contract Adversary {
    // some storage to be changed if executed in this contract's context
    uint256 public marker;

    // match selector: transferFrom(address,address,uint256)
    // calldata parameters are ignored; calling this will mutate storage
    function transferFrom(address, address, uint256) public returns (bool) {
        // modify storage in this contract
        marker = 123;
        return true;
    }

    // fallback to accept delegatecall/call with selector
    fallback() external {}
}

