pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an address 'from', an array length indicator 'n', a value v.
    // The adversarial callee will, when called, perform a revert for some to-address or mutate storage if delegatecall is used.
    function testFuzz_property(address from, uint256 n, uint256 v) public {
        // Keep domain wide but sensible: array length small to keep gas bounded
        uint256 len = bound(n, 1, 5); // require(_tos.length > 0) in C

        // Build tos array of helper addresses (all pointing to the same adversary contract)
        Adversary adv = new Adversary();
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(adv);

        // The adversary will revert when it sees a specific v marker (we let fuzzer choose v).
        // Ensure from is a non-zero address to be realistic
        if (from == address(0)) from = address(1);

        // Call C.transfer and capture whether it succeeded (did not revert).
        bool ok;
        try c.transfer(from, address(adv), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: For the reference implementation, transfer never reverts for any inputs
        // when calling an external callee contract (it uses call and bubbles up failure), and so
        // must return true (ok == true). We assert that property here; the delegatecall mutant
        // can cause the call to revert or change behavior for some v and will fail this assertion.
        assertTrue(ok);
    }
}

// Adversarial callee: when invoked with selector transferFrom(address,address,uint256),
// it will revert if the amount equals a magic marker chosen by the fuzzer; otherwise it does nothing.
// This models a callee that may revert or mutate state; under delegatecall such behavior could affect C.
contract Adversary {
    // receive arguments via calldata; decode last parameter uint256 v and revert when v is a particular value
    fallback() external payable {
        // decode calldata expecting (address from, address to, uint256 v)
        if (msg.data.length >= 96) {
            // last 32 bytes are v
            uint256 v;
            assembly { v := calldataload(sub(calldatasize(), 32)) }
            // choose a marker value that is unlikely but fuzzer can hit; we pick 0xdead as marker
            if (v == 0xdead) {
                revert("marker");
            }
        }
    }
}

